import{_ as a,c as i,o as t,b0 as o}from"./chunks/framework.Dmsv_Tiv.js";const r="/media-docs/assets/d46613d0b255f952a44d872c28ad322d.D8UfyKMj.png",s="/media-docs/assets/00abd2f56b7305f88322458783d2ed55.RF6PpWYp.png",l="/media-docs/assets/0e94a142ed5efc0e70dadbca7e7a6a2b.BncTQ-1B.png",n="/media-docs/assets/e31da80f961f062fe5bf52080e86d46d.DOIin8PV.png",c="/media-docs/assets/d96a8b43d6557c303c9f2e7de242d527.XTYOqmB6.png",p="/media-docs/assets/d1fdcbaa2436a2ce99ce5b94b763d223.Dt2rArAK.png",d="/media-docs/assets/6084a79918d3102f9c12d5d19f5fa6fc.DX3oLK8Q.png",m="/media-docs/assets/d2ad4be2f4df394ab53f5cd1367a6a03.B12D3JG7.png",M=JSON.parse('{"title":"LV005-MIPI简介","description":null,"frontmatter":{"title":"LV005-MIPI简介","date":"2025-11-07T09:14:14.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/mipi/mipi-intro/126b140b63d636e6bb6435d6","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-11-07T09:14:14.878Z","fulluuid":"6bb6435d6a274e74803aa0be1a821326","useduuid":"6bb6435d6"}},"headers":[],"relativePath":"sdoc/mipi/mipi-intro/126b140b63d636e6bb6435d6.md","filePath":"sdoc/15-MIPI/05-MIPI简介/LV005-MIPI简介.md","lastUpdated":1767537778000}'),I={name:"sdoc/mipi/mipi-intro/126b140b63d636e6bb6435d6.md"};function u(h,e,b,f,g,P){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="lv005-mipi简介" tabindex="-1">LV005-MIPI简介 <a class="header-anchor" href="#lv005-mipi简介" aria-label="Permalink to &quot;LV005-MIPI简介&quot;">​</a></h1><p>在学习相机开发过程中，离不开的就是这个 MIPI，那么他到底是什么？</p><h2 id="一、mipi-是什么" tabindex="-1">一、MIPI 是什么？ <a class="header-anchor" href="#一、mipi-是什么" aria-label="Permalink to &quot;一、MIPI 是什么？&quot;">​</a></h2><h3 id="_1-简介" tabindex="-1">1. 简介 <a class="header-anchor" href="#_1-简介" aria-label="Permalink to &quot;1. 简介&quot;">​</a></h3><p>我们先去官网看一眼：<a href="https://www.mipi.org/" target="_blank" rel="noreferrer">Interface Specifications for Mobile Products | MIPI Allliance</a>。我们来到 About Us 这个页面可以看到这样一段介绍：</p><blockquote><p>MIPI Alliance is a collaborative global organization serving industries that develop mobile and mobile-influenced devices. The focus of the organization is to design and promote hardware and software interfaces that simplify the integration of components built into a device, from the antenna and modem, to peripherals and the application processor. MIPI Alliance crafts all of its specifications to meet the stringent operating conditions required in mobile devices: high-bandwidth performance, low power consumption, and low electromagnetic interference (EMI).</p><p>英语看不懂？哈哈，我们放到翻译软件翻译一下就是：</p><p><strong>MIPI 联盟是一个全球性的协作组织</strong>，为开发移动和受移动影响的设备的行业提供服务。该组织的重点是 <strong>设计和推广硬件和软件接口</strong>，以简化内置到设备中的组件的集成，从天线和调制解调器到外围设备和应用处理器。MIPI 联盟制定的所有规格都符合移动设备所需的严格操作条件：高带宽性能、低功耗和低电磁干扰（EMI）。</p></blockquote><p>MIPI，全称为 Mobile Industry Processor Interface，即移动行业处理器接口。它是 MIPI 联盟（ARM、诺基亚、TI 等）发起的为移动应用处理器制定的开放标准。MIPI 接口是一种专为移动设备和嵌入式系统设计的串行通信接口，定义了一系列的接口标准。</p><blockquote><p>在 MIPI 联盟的中国成员中，仅 7 家公司是作为 contributor 身份存在，包括海思、卓胜微等，多家公司以 adopter 身份存在，例如全志、瑞芯微、小米、VIVO 等。</p></blockquote><h3 id="_2-发展" tabindex="-1">2. 发展 <a class="header-anchor" href="#_2-发展" aria-label="Permalink to &quot;2. 发展&quot;">​</a></h3><p>2000 年代初，功能手机向智能手机过渡时，摄像头、显示屏等模块的接口标准混乱（LVDS、并行总线等），存在 <strong>高功耗、高 EMI、带宽瓶颈</strong> 问题。厂商各自为政，供应链成本高企，亟需 <strong>标准化</strong> 以加速产品迭代。</p><p>2003 年，由 ARM、诺基亚、TI 等牵头成立 MIPI 联盟，目标是通过 <strong>开放协作</strong> 制定低功耗、高性能的移动端专用接口。关键理念：<strong>分层协议设计</strong>（物理层+协议层解耦），兼顾灵活性与扩展性。</p><p>中间怎么发展的，就没有去详细了解了。此处省略......但是官网好像有历史介绍：<a href="https://www.mipi.org/about-us" target="_blank" rel="noreferrer">About Us | MIPI</a></p><h2 id="二、框架" tabindex="-1">二、框架 <a class="header-anchor" href="#二、框架" aria-label="Permalink to &quot;二、框架&quot;">​</a></h2><h3 id="_1-四个方面的协议" tabindex="-1">1. 四个方面的协议 <a class="header-anchor" href="#_1-四个方面的协议" aria-label="Permalink to &quot;1. 四个方面的协议&quot;">​</a></h3><p>MIPI 主要包含四个方面的协议：</p><img src="'+r+'" alt="img" style="zoom:25%;"><ul><li>multimedia，多媒体，最常见</li><li>Control&amp;Data</li><li>Chip-to-Chip Inter Process Communications</li><li>Debug &amp; Trace</li></ul><h3 id="_2-都有什么用" tabindex="-1">2. 都有什么用？ <a class="header-anchor" href="#_2-都有什么用" aria-label="Permalink to &quot;2. 都有什么用？&quot;">​</a></h3><p>四个方面分别包含如下用途，以颜色区分</p><img src="'+s+'" alt="img" style="zoom:67%;"><h4 id="_2-1-mipi-multimedia-spec" tabindex="-1">2.1 <strong>MIPI multimedia spec</strong> <a class="header-anchor" href="#_2-1-mipi-multimedia-spec" aria-label="Permalink to &quot;2.1 **MIPI multimedia spec**&quot;">​</a></h4><p>其中最常见的多媒体方向的协议，大家讨论的大都是多媒体方面的：</p><img src="'+l+'" alt="img" style="zoom:67%;"><blockquote><p>后面重点学习的就是用于 Camera 的 CSI。</p></blockquote><p>上图分为三层：应用层、协议层、物理层。</p><ul><li><p>DSI：Display Serial Interface，定义位于处理器和显示模组之间的高速串行接口。</p></li><li><p>CSI：Camera Serial Interface，定义位于处理器和摄像模组之间的高速串行接口。</p></li><li><p>DCS：Display Command Set，一个标准化的命令集，用于命令模式的显示模组。</p></li><li><p>D-PHY、C-PHY、A-PHY、M-PHY：提供 DSI 和 CSI 的物理层定义，其中大家讨论最多的是 D-PHY 这个协议，用的最多的也是 D-PHY。</p></li></ul><h4 id="_2-2-mipi-control-data" tabindex="-1">2.2 MIPI Control &amp; Data <a class="header-anchor" href="#_2-2-mipi-control-data" aria-label="Permalink to &quot;2.2 MIPI Control &amp; Data&quot;">​</a></h4><img src="'+n+'" alt="img" style="zoom:50%;"><h4 id="_2-3-mipi-chip-to-chip-communications-spec" tabindex="-1">2.3 MIPI Chip-to-Chip Communications spec <a class="header-anchor" href="#_2-3-mipi-chip-to-chip-communications-spec" aria-label="Permalink to &quot;2.3 MIPI Chip-to-Chip Communications spec&quot;">​</a></h4><img src="'+c+'" alt="img" style="zoom:50%;"><h4 id="_2-4-mipi-debug-spec" tabindex="-1">2.4 MIPI Debug spec <a class="header-anchor" href="#_2-4-mipi-debug-spec" aria-label="Permalink to &quot;2.4 MIPI Debug spec&quot;">​</a></h4><ul><li>MIPI Debug Specifications for Dedicated Debug Interfaces</li></ul><img src="'+p+'" alt="img" style="zoom:67%;"><ul><li>MIPI Debug Specifications for Networked Interfaces</li></ul><img src="'+d+'" alt="img" style="zoom:67%;"><ul><li>MIPI Debug Specifications for PHY &amp; Pin Overlaid Interfaces</li></ul><img src="'+m+'" alt="img" style="zoom:67%;"><blockquote><p>参考资料：</p><p><a href="https://mp.weixin.qq.com/s/-zesW2WfxGLYo9boODXmLA" target="_blank" rel="noreferrer">一文看懂 | MIPI 的前世今生及 MIPI 多媒体系统</a></p><p><a href="https://mp.weixin.qq.com/s/fhYqP3uuqxekBmCj1iK20Q" target="_blank" rel="noreferrer">ATE 唠唠嗑 No.11——MIPI 浅谈</a></p><p><a href="https://mp.weixin.qq.com/s/zec8xRPC2CXoyxdgaFYBTA" target="_blank" rel="noreferrer">MIPI 简介(一)——基础概念介绍</a></p><p><a href="https://cloud.tencent.com/developer/article/1943922" target="_blank" rel="noreferrer">一文带你搞懂 MIPI 框架-腾讯云开发者社区-腾讯云</a></p></blockquote>',38)])])}const q=a(I,[["render",u]]);export{M as __pageData,q as default};
